function localQuakeLocation(value: string, lang: Lang): string {
  const parts = value.split(',').map((part) => part.trim());
  return parts.map((part) => COUNTRY_NAMES[part]?.[lang] ?? (localCity(part, lang) !== part ? localCity(part, lang) : localRegion(part, lang))).join(', ');
}

export function localQuakePlace(value: string, lang: Lang): string {
  const match = value.match(/^([\d.]+)\s*km\s+([NSEW]{1,3})\s+of\s+(.+)$/i);
  if (!match) return localQuakeLocation(value, lang);
  const distance = formatNumber(lang, Number(match[1]), { maximumFractionDigits: 1 });
  const direction = DIRECTIONS[match[2].toUpperCase()]?.[lang] ?? match[2];
  const place = localQuakeLocation(match[3], lang);
  return t(lang, '{distance} km {direction} of {place}', { distance, direction, place });
}
